application/json.schema:
{
  "title": "Tech Stack Detector input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "urls": {
      "title": "Websites",
      "type": "array",
      "description": "Website URLs or bare domains, one per line (for example `shopify.com` or `https://www.example.com/pricing`). Each site is checked once; duplicates are skipped.",
      "editor": "stringList",
      "prefill": [
        "https://www.allbirds.com",
        "https://techcrunch.com",
        "https://vercel.com"
      ],
      "default": [
        "https://www.allbirds.com",
        "https://techcrunch.com",
        "https://vercel.com"
      ]
    },
    "checkDns": {
      "title": "Check email and DNS records",
      "type": "boolean",
      "description": "Also read the domain's MX and TXT records to find the email provider (Google Workspace, Microsoft 365) and email and SaaS tools (SendGrid, Mailchimp, HubSpot, Zendesk and more). Free; adds under a second per site.",
      "default": true
    },
    "timeoutSecs": {
      "title": "Timeout per site (seconds)",
      "type": "integer",
      "description": "How long to wait for each site before skipping it. Skipped sites are not charged.",
      "default": 20,
      "minimum": 5,
      "maximum": 60,
      "unit": "seconds"
    }
  },
  "required": [
    "urls"
  ]
}

